(()=>{
const campus=!!document.querySelector('#studyPage'),esc=growthEscape;let page='explore',selected=null,feedback='',saving=false,previousFocus;
const dialog=document.createElement('dialog');dialog.className='career-book';dialog.setAttribute('aria-label','별빛도서관 진로 책장');document.body.append(dialog);
async function open(){previousFocus=document.activeElement;document.querySelector('.compact-menu')?.close();page='explore';selected=null;feedback='';draw();dialog.showModal();await loadGrowth();draw()}
const menuButton=document.createElement('button');menuButton.textContent='📚 진로 책장';menuButton.onclick=open;document.querySelector('.compact-menu-grid').append(menuButton);
const shortcut=document.createElement('button');shortcut.id='openCareer';shortcut.textContent='📚 진로 책장';shortcut.onclick=open;(campus?document.querySelector('.study-compact-tabs'):document.querySelector('#compactQuiz')).append(shortcut);
dialog.addEventListener('close',()=>previousFocus?.focus());
async function action(payload){if(saving)return false;saving=true;dialog.querySelectorAll('button').forEach(b=>b.disabled=true);try{const auth=sessionStorage.getItem('village-student-token');if(!auth)throw Error('학급으로 입장하면 내 기록을 저장할 수 있어요.');const r=await fetch('/api/action',{method:'POST',headers:{'content-type':'application/json',authorization:'Bearer '+auth},body:JSON.stringify({...payload,requestId:crypto.randomUUID()}),signal:AbortSignal.timeout(20000)});const d=await r.json();if(!r.ok)throw Error(d.error||'저장을 확인해 주세요.');if(!campus)applySchool(d);await loadGrowth();return true}catch(e){feedback=e.name==='TimeoutError'?'저장 확인이 늦어요. 다시 누르면 같은 기록으로 저장됩니다.':e.message;return false}finally{saving=false;dialog.querySelectorAll('button').forEach(b=>b.disabled=false)}}
function draw(){const d=growthBoard?.career;dialog.innerHTML=`<header><div><small>별빛도서관</small><h2>나의 진로 책장</h2></div><button data-close-career aria-label="진로 책장 닫기">✕</button></header><nav>${[['explore','교과 탐험'],['quiz','탐험 퀴즈'],['cart','내 장바구니'],['guide','대학·진학 안내']].map(([id,name])=>`<button data-career-page="${id}" aria-pressed="${page===id}">${name}</button>`).join('')}</nav><div class="career-content">${!d?'<p>학급으로 입장하면 탐험과 내 기록을 볼 수 있어요.</p><button data-retry-career>다시 불러오기</button>':content(d)}</div><p role="status" class="career-feedback">${esc(feedback)}</p>`}
function content(d){if(page==='guide')return '<h3>관심 → 과목 → 학과 → 다양한 직업</h3><p>여기서 담은 과목은 나의 관심 기록이에요. 실제 수강 신청이나 대학 합격 조건이 아닙니다. 학교에 개설된 과목과 이수 순서를 선생님과 확인해 보세요.</p><ol><li>관심 학과에서 배우는 수업을 찾아요.</li><li>대학의 공식 입학처에서 지원 연도의 권장과목을 확인해요.</li><li>우리 학교 교육과정과 비교하고 상담해요.</li></ol><p><a target="_blank" rel="noopener" href="https://claude.ai/artifact/AqH18hyNowBnpdgvo9M2tw">선생님의 기존 과목 장바구니 열기 ↗</a></p><p>외부 장바구니와 게임 기록은 자동으로 합쳐지지 않아요. 외부 자료의 권장과목은 대학 공식 안내로 다시 확인하세요.</p><p><a target="_blank" rel="noopener" href="https://www.goe.go.kr/resource/old/BBSMSTR_000000030136/BBS_202312050603474391.pdf">2022 개정 교육과정 과목 선택 안내 ↗</a></p><p><a target="_blank" rel="noopener" href="https://www.gne.go.kr/h-creditsystem/education/operation/operation_2026.jsp">경남 공동교육과정 운영 안내 ↗</a></p><small>2022 개정 교육과정 기준 · 2026.09.22 구성. 학과·직업 연결은 탐색 예시입니다.</small>';
if(page==='cart')return '<h3>내가 배우고 싶은 과목</h3><p>선택 이유는 내 계정에 저장돼요. 다른 학생에게 공개되지 않아요.</p>'+ (Object.entries(d.cart).map(([course,reason])=>`<article class="career-card"><b>${esc(course)}</b><p>${esc(reason)}</p><button data-edit-course="${esc(course)}">이유 수정</button><button data-remove-course="${esc(course)}">빼기</button></article>`).join('')||'<p>아직 담은 과목이 없어요. 교과 탐험에서 관심 과목을 찾아보세요.</p>');
if(page==='quiz'){const list=d.questions,q=selected?list.find(q=>q.id===selected):list.find(q=>!d.solved.includes(q.id));if(!q)return `<h3>24개 탐험을 마쳤어요!</h3><p>관심 과목을 담고 선택 이유를 적어 보세요.</p><button data-career-page="explore">교과 탐험으로</button>`;const done=d.solved.includes(q.id);return `<p>${q.kind} 탐험 · ${d.solved.length} / ${list.length}개 완료 · 자유 탐험은 코인 대신 기록과 도장을 쌓아요.</p><h3>${esc(q.prompt)}</h3><div class="career-answers">${q.choices.map((x,i)=>({x,i})).sort((a,b)=>((a.i+q.id.length)%3)-((b.i+q.id.length)%3)).map(({x,i})=>`<button data-career-answer="${i}" data-question="${q.id}" ${done?'disabled':''}>${esc(x)}</button>`).join('')}</div>${done?`<p class="career-explanation">✓ ${esc(q.explanation)}</p><button data-path="${q.path}">연결 과목 살펴보기</button><button data-next-question>다음 탐험</button>`:`<details><summary>과목 설명에서 단서 찾기</summary><p>${esc(q.explanation)}</p></details>`}`}
if(selected){const p=d.pathways.find(p=>p.id===selected);if(p)return `<button data-career-page="explore">← 활동 목록</button><h3>${p.icon} ${esc(p.title)}</h3><p>${esc(p.situation)}</p><p>${esc(p.explanation)}</p><p>함께 살펴볼 분야: ${esc(p.major)} · ${esc(p.job)}</p><p>기초와 심화 과목의 이수 순서는 학교에서 확인해요.</p>${[p.course,p.related].map(c=>`<button data-edit-course="${esc(c)}">${esc(c)} · ${d.cart[c]?'담김 / 수정':'관심 과목 담기'}</button>`).join('')}<p><button data-question-start="${p.id}-course">이 활동 퀴즈 풀기</button></p>`}
return '<p>마을에서 궁금했던 일을 골라 보세요. 여러 교과를 함께 배울 수 있어요.</p><div class="career-grid">'+d.pathways.map(p=>`<button class="career-card" data-path="${p.id}"><span>${p.icon}</span><b>${esc(p.title)}</b><small>${esc(p.course)} · ${esc(p.related)}</small></button>`).join('')+'</div>'}
function edit(course){const d=growthBoard.career;dialog.querySelector('.career-content').innerHTML=`<h3>${esc(course)}</h3><label>이 과목에서 무엇을 배우고 싶나요?<textarea id="careerReason" maxlength="200" rows="4" placeholder="예: 수확 기록을 분석해 물 주는 방법을 비교하고 싶어요.">${esc(d.cart[course]||'')}</textarea></label><button id="saveCareerReason">내 장바구니에 저장</button>`;dialog.querySelector('#saveCareerReason').onclick=async()=>{const reason=dialog.querySelector('#careerReason').value;if(reason.trim().length<2){dialog.querySelector('.career-feedback').textContent='선택 이유를 두 글자 이상 적어 주세요.';return}const ok=await action({action:'career_save',course,reason});if(ok){page='cart';feedback='내 관심 과목과 이유를 저장했어요.';draw()}else dialog.querySelector('.career-feedback').textContent=feedback};dialog.querySelector('textarea').focus()}
dialog.onclick=async e=>{const b=e.target.closest('button');if(!b||saving)return;if(b.hasAttribute('data-close-career')){dialog.close();return}if(b.hasAttribute('data-retry-career')){await loadGrowth();draw();return}if(b.dataset.editCourse){edit(b.dataset.editCourse);return}if(b.dataset.removeCourse){if(await action({action:'career_save',course:b.dataset.removeCourse,remove:true}))feedback='장바구니에서 뺐어요.';draw();return}if(b.dataset.careerPage){page=b.dataset.careerPage;selected=null;feedback='';draw()}if(b.dataset.path){page='explore';selected=b.dataset.path;feedback='';draw()}if(b.dataset.questionStart){page='quiz';selected=b.dataset.questionStart;feedback='';draw()}if(b.hasAttribute('data-next-question')){selected=null;feedback='';draw()}if(b.dataset.careerAnswer!==undefined){selected=b.dataset.question;const ok=await action({action:'career_answer',question:selected,answer:Number(b.dataset.careerAnswer)});if(ok)feedback='탐험 기록이 저장됐어요!';draw()}};
if(!campus){const help=document.createElement('details');help.className='first-steps';help.innerHTML='<summary>🌱 처음 왔나요? 마을 길잡이</summary><div id="firstSteps"></div>';document.querySelector('#farmScene').before(help);function guide(){const s=state,c=growthBoard?.career;const steps=[['첫 수확',(s.farm?.picked||0)>0,'빈 밭에 씨앗을 심고 다시 눌러 물을 주세요. 자라면 수확해요.'],['직업 알아보기',(s.quizSolved?.length||0)>0,'활동 → 오늘의 퀴즈에서 직업 문제를 풀어요.'],['함께 나누기',(s.garden?.given||[]).some(x=>x>0),'활동 → 공동 도시락에서 수확물을 기부해요. 장터가 닫혀 있어도 할 수 있어요.']];help.querySelector('#firstSteps').innerHTML=steps.map(([t,done,desc])=>`<p><b>${done?'✓':'○'} ${t}</b> · ${desc}</p>`).join('')+'<p>장날에는 메뉴 → 장터에서 친구와 교환해요. 별빛도서관에서는 공부와 진로 탐험을 할 수 있어요.</p><button id="hideTutorial">안내 접기</button>';help.querySelector('button').onclick=async()=>{help.open=false;if(sessionStorage.getItem('village-student-token'))await action({action:'tutorial_hide',hidden:true})};if(c&&!c.tutorialHidden&&!help.dataset.presented){help.open=true;help.dataset.presented='1'}}const old=drawGrowth;drawGrowth=function(){old();guide()};guide()}
})();
